import 'dart:async';
import 'package:flutter/material.dart';
import 'auth_store.dart';
import 'api.dart';
import 'local_store.dart';
import 'sync_service.dart';
import 'push_service.dart';

void main(){WidgetsFlutterBinding.ensureInitialized();PushService.installBackgroundHandler();runApp(const PlannerApp());}

class PlannerApp extends StatelessWidget{
  const PlannerApp({super.key});
  @override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Planner',theme:ThemeData(useMaterial3:true,colorSchemeSeed:const Color(0xff315c4b),scaffoldBackgroundColor:const Color(0xfffafafa),inputDecorationTheme:const InputDecorationTheme(border:OutlineInputBorder())),home:const Gate());
}

class Gate extends StatefulWidget{const Gate({super.key});@override State<Gate> createState()=>_GateState();}
class _GateState extends State<Gate>{bool? has;@override void initState(){super.initState();AuthStore.hasSession().then((v){if(mounted)setState(()=>has=v);});}@override Widget build(BuildContext c)=>has==null?const Scaffold(body:Center(child:CircularProgressIndicator())):has!?const Home():const Login();}

class Login extends StatefulWidget{const Login({super.key});@override State<Login> createState()=>_LoginState();}
class _LoginState extends State<Login>{final email=TextEditingController(),pass=TextEditingController();String? err;bool busy=false;Future<void> go()async{setState(()=>busy=true);try{final r=Map<String,dynamic>.from(await Api.call('/auth/login',method:'POST',body:{'email':email.text.trim(),'password':pass.text,'platform':'mobile','device_name':'personal-phone'}));await AuthStore.save(r);if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const Home()));}catch(_){if(mounted)setState(()=>err='ورود انجام نشد');}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:420),child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('برنامه‌ریز',textAlign:TextAlign.right,style:TextStyle(fontSize:30,fontWeight:FontWeight.w700)),const SizedBox(height:8),const Text('اطلاعات قبلی روی همین گوشی می‌ماند و پس از ورود همگام می‌شود.',textAlign:TextAlign.right),const SizedBox(height:28),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'ایمیل')),const SizedBox(height:12),TextField(controller:pass,obscureText:true,decoration:const InputDecoration(labelText:'رمز عبور')),if(err!=null)Padding(padding:const EdgeInsets.only(top:10),child:Text(err!,textAlign:TextAlign.right)),const SizedBox(height:18),FilledButton(onPressed:busy?null:go,child:Text(busy?'...':'ورود'))])))))));}

typedef ActionFn=Future<void> Function(String,String,String);
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{int tab=0;List<Map<String,dynamic>> tasks=[],events=[];bool localLoading=true;bool syncing=false;Timer? _retry;
  @override void initState(){super.initState();_openLocal();}
  @override void dispose(){_retry?.cancel();super.dispose();}
  Future<void> _openLocal()async{final t=await LocalStore.list('task');final e=await LocalStore.list('event');if(mounted)setState((){tasks=t;events=e;localLoading=false;});unawaited(PushService.initialize());unawaited(_sync());}
  Future<void> _reloadLocal()async{final t=await LocalStore.list('task');final e=await LocalStore.list('event');if(mounted)setState((){tasks=t;events=e;});}
  Future<void> _sync()async{if(syncing)return;setState(()=>syncing=true);await SyncService.sync();await _reloadLocal();if(mounted)setState(()=>syncing=false);}
  Future<void> act(String kind,String id,String action)async{final list=kind=='task'?tasks:events;final i=list.indexWhere((x)=>x['id']==id);if(i<0)return;final x=Map<String,dynamic>.from(list[i]);if(action=='complete'){x['status']='completed';x['completed_at']=DateTime.now().toIso8601String();}else{x['status']='open';}await LocalStore.upsert(kind,x);await LocalStore.enqueue('POST','/${kind}s/$id/$action',action=='continue'?{}:null);await _reloadLocal();unawaited(_sync());}
  void addTask(){final ctl=TextEditingController();showModalBottomSheet(context:context,isScrollControlled:true,useSafeArea:true,builder:(sheet)=>Padding(padding:EdgeInsets.fromLTRB(20,20,20,24+MediaQuery.of(sheet).viewInsets.bottom),child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:ctl,autofocus:true,textDirection:TextDirection.rtl,decoration:const InputDecoration(labelText:'چه کاری باید انجام شود؟')),const SizedBox(height:12),SizedBox(width:double.infinity,child:FilledButton(onPressed:()async{final title=ctl.text.trim();if(title.isEmpty)return;final id='local-${DateTime.now().microsecondsSinceEpoch}';await LocalStore.upsert('task',{'id':id,'title':title,'status':'open','created_at':DateTime.now().toIso8601String(),'local_only':true});await LocalStore.enqueue('POST','/tasks',{'title':title});if(sheet.mounted)Navigator.pop(sheet);await _reloadLocal();unawaited(_sync());},child:const Text('ثبت کار')))]))));}
  @override Widget build(BuildContext c){final pages=[Today(tasks:tasks,events:events,onAct:act),Items(kind:'task',items:tasks,onAct:act),Items(kind:'event',items:events,onAct:act)];return Scaffold(appBar:AppBar(title:Text(tab==0?'امروز':tab==1?'کارها':'رویدادها'),actions:[if(syncing)const Padding(padding:EdgeInsets.all(14),child:SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2))),IconButton(onPressed:_sync,icon:const Icon(Icons.sync_rounded))]),body:localLoading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:_sync,child:pages[tab]),floatingActionButton:SafeArea(minimum:const EdgeInsets.only(bottom:8),child:FloatingActionButton(onPressed:addTask,child:const Icon(Icons.add))),floatingActionButtonLocation:FloatingActionButtonLocation.endFloat,bottomNavigationBar:SafeArea(top:false,child:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const [NavigationDestination(icon:Icon(Icons.today_outlined),selectedIcon:Icon(Icons.today),label:'امروز'),NavigationDestination(icon:Icon(Icons.check_circle_outline),label:'کارها'),NavigationDestination(icon:Icon(Icons.calendar_month_outlined),label:'رویدادها')])));}
}

class Today extends StatelessWidget{final List<Map<String,dynamic>> tasks,events;final ActionFn onAct;const Today({super.key,required this.tasks,required this.events,required this.onAct});@override Widget build(BuildContext c){final open=tasks.where((x)=>x['status']!='completed').toList(),ev=events.where((x)=>x['status']!='completed').toList();return ListView(physics:const AlwaysScrollableScrollPhysics(),padding:const EdgeInsets.all(16),children:[const Text('کارهای نزدیک',style:TextStyle(fontSize:18,fontWeight:FontWeight.w700)),const SizedBox(height:8),if(open.isEmpty)const Empty(text:'کاری برای نمایش نیست'),...open.map((x)=>ItemCard(x:x,kind:'task',onAct:onAct)),const SizedBox(height:18),const Text('رویدادها',style:TextStyle(fontSize:18,fontWeight:FontWeight.w700)),const SizedBox(height:8),if(ev.isEmpty)const Empty(text:'رویدادی ثبت نشده'),...ev.map((x)=>ItemCard(x:x,kind:'event',onAct:onAct))]);}}
class Items extends StatelessWidget{final String kind;final List<Map<String,dynamic>> items;final ActionFn onAct;const Items({super.key,required this.kind,required this.items,required this.onAct});@override Widget build(BuildContext c)=>ListView(physics:const AlwaysScrollableScrollPhysics(),padding:const EdgeInsets.all(16),children:items.isEmpty?[const Empty(text:'هنوز چیزی ثبت نشده')]:items.map((x)=>ItemCard(x:x,kind:kind,onAct:onAct)).toList());}
class ItemCard extends StatelessWidget{final Map<String,dynamic> x;final String kind;final ActionFn onAct;const ItemCard({super.key,required this.x,required this.kind,required this.onAct});@override Widget build(BuildContext c)=>Card(elevation:0,margin:const EdgeInsets.only(bottom:10),child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Row(children:[if(x['local_only']==true)const Padding(padding:EdgeInsets.only(right:8),child:Icon(Icons.cloud_off_outlined,size:16)),Expanded(child:Text(x['title']??'',textAlign:TextAlign.right,style:const TextStyle(fontWeight:FontWeight.w600,fontSize:16)))]),const SizedBox(height:12),Row(children:[Expanded(child:OutlinedButton(onPressed:()=>onAct(kind,x['id'].toString(),'continue'),child:const Text('ادامه دارد'))),const SizedBox(width:8),Expanded(child:FilledButton(onPressed:()=>onAct(kind,x['id'].toString(),'complete'),child:const Text('انجام شد')))])])));}
class Empty extends StatelessWidget{final String text;const Empty({super.key,required this.text});@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.symmetric(vertical:24),child:Text(text,textAlign:TextAlign.center,style:TextStyle(color:Theme.of(c).colorScheme.onSurfaceVariant)));}
